// NotifyGateway-Go / Zabbix 7.0 LTS Webhook.
// Version: 1.1.0 / 2026-10-13
// Problem uses EVENT.ID/EVENT.VALUE. Recovery uses EVENT.RECOVERY.ID/EVENT.RECOVERY.VALUE.
var p;
try { p = JSON.parse(value); } catch (e) { throw '媒介参数不是有效 JSON'; }
if (!p || typeof p !== 'object' || Array.isArray(p)) { throw '媒介参数必须是 JSON 对象'; }
function unresolved(v) { return typeof v !== 'string' || v === '' || v === '*UNKNOWN*' || /^\{[^{}]+\}$/.test(v); }
function required(name) { var v = p[name]; if (unresolved(v) || /^\s*$/.test(v)) { throw '参数 ' + name + ' 缺失或宏未展开'; } return v; }
function testText(name, fallback) { return unresolved(p[name]) || /^\s*$/.test(p[name]) ? fallback : p[name]; }
function validateDate(name, v) { var m = /^(\d{4})\.(\d{2})\.(\d{2})$/.exec(v); if (!m) { throw '参数 ' + name + ' 格式无效：应为 YYYY.MM.DD'; } var y=Number(m[1]), mo=Number(m[2]), d=Number(m[3]); var days=[31,((y%4===0&&y%100!==0)||y%400===0)?29:28,31,30,31,30,31,31,30,31,30,31]; if (y<1||mo<1||mo>12||d<1||d>days[mo-1]) { throw '参数 ' + name + ' 不是有效日历日期'; } }
function validateTime(name, v) { if (!/^([01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(v)) { throw '参数 ' + name + ' 格式无效：应为 HH:MM:SS'; } }
var mode = typeof p.test_mode === 'undefined' ? '0' : String(p.test_mode);
if (mode !== '0' && mode !== '1') { throw 'test_mode 只能是 0（正式事件）或 1（合成测试）'; }
var url = required('url'); var token = required('token');
if (!/^https?:\/\/[^\s]+\/api\/v1\/ingress\/[a-z][a-z0-9_-]{0,63}$/.test(url) || /CHANGE-ME|example\.invalid/i.test(url) || /^https?:\/\/[^/]*@/.test(url)) { throw 'url 必须是完整 NotifyGateway ingress 地址'; }
if (token === 'REPLACE_WITH_ZABBIX_SOURCE_TOKEN' || token.length < 32 || /[\s\x00-\x1f\x7f]/.test(token) || /^Bearer /i.test(token)) { throw 'token 必须填写实际 Zabbix Source Token；不要添加 Bearer 前缀'; }
var payload;
if (mode === '1') { var now=new Date(); var ts=(typeof p.severity==='string'&&/^[0-5]$/.test(p.severity))?Number(p.severity):2; payload={event_id:'media-test-'+String(now.getTime())+'-'+String(Math.floor(Math.random()*1000000)),event_type:'test',event_time:now.toISOString(),host:testText('host','zabbix-media-test'),severity:ts,name:testText('name','NotifyGateway-Go 媒介连通测试'),message:'[合成测试] '+testText('message','Zabbix Media type 测试消息')}; }
else { if (required('event_source') !== '0') { throw 'event_source 必须是 0；本媒介仅支持 Trigger 事件'; } var ev=required('event_value'); if (ev !== '1') { throw '正式 Trigger 通知中的 EVENT.VALUE 应为 1；恢复状态请使用 EVENT.RECOVERY.VALUE'; } var problemID=required('event_id'); var rv=unresolved(p.recovery_value)?'':String(p.recovery_value); var rid=unresolved(p.recovery_event_id)?'':String(p.recovery_event_id); var recovery=rv==='0'&&rid!==''; if ((rv==='0'&&rid==='')||(rv!==''&&rv!=='0')) { throw '恢复事件宏状态不一致：检查 EVENT.RECOVERY.VALUE/ID'; } var dn=recovery?'recovery_date':'event_date'; var tn=recovery?'recovery_time':'event_time'; var date=required(dn), clock=required(tn); validateDate(dn,date); validateTime(tn,clock); var offset=required('utc_offset'); if (!/^[+-](0\d|1[0-3]):[0-5]\d$/.test(offset)&&!/^[+-]14:00$/.test(offset)) { throw 'utc_offset 格式无效，例如北京时间填写 +08:00'; } var sev=required('severity'); if (!/^[0-5]$/.test(sev)) { throw 'severity 必须是 0-5'; } payload={event_id:recovery?rid:problemID,event_type:recovery?'recovery':'problem',event_time:date.replace(/\./g,'-')+'T'+clock+offset,problem_event_id:problemID,host:required('host'),severity:Number(sev),name:required('name'),message:(typeof p.message==='string'&&!unresolved(p.message))?p.message:''}; }
if (typeof p.host_ip==='string'&&p.host_ip!==''&&p.host_ip.indexOf('{')===-1&&p.host_ip!=='*UNKNOWN*') { payload.host_ip=p.host_ip; }
var req=new HttpRequest(); req.addHeader('Content-Type: application/json'); req.addHeader('Authorization: Bearer '+token); Zabbix.log(4,'[NotifyGateway-Go] sending '+payload.event_type+' event_id='+payload.event_id+' host='+payload.host); var response; try { response=req.post(url,JSON.stringify(payload)); } catch(e) { throw 'NotifyGateway HTTP 请求失败：'+e; } var status=Number(req.getStatus());
if (status!==202) { var hint=''; if (status===401||status===403) hint='检查 Source ID、Bearer Token 和访问限制'; else if (status===404) hint='检查 ingress 路径及 Source 是否存在'; else if (status===400||status===422) hint='检查发送字段、日期、严重度和事件类型'; else if (status===429) hint='接入并发或来源速率受限'; else if (status===503) hint='检查路由、容量、存储和运行状态'; else hint='检查 NotifyGateway 日志'; throw 'NotifyGateway HTTP '+status+'；'+hint; }
if (typeof response!=='string'||response.length===0||response.length>1048576) { throw 'NotifyGateway HTTP 202 响应为空或超限；网关可能已接管，请检查网关日志'; } var result; try { result=JSON.parse(response); } catch(e) { throw 'NotifyGateway HTTP 202 响应不是有效 JSON；网关可能已接管'; }
if (!result||result.mode!=='SERVE'||typeof result.request_id!=='string'||result.request_id===''||!Array.isArray(result.events)||result.events.length!==1||!Array.isArray(result.delivery_ids)||typeof result.delivery_obligation_count!=='number'||!isFinite(result.delivery_obligation_count)||result.delivery_obligation_count<0||Math.floor(result.delivery_obligation_count)!==result.delivery_obligation_count||result.delivery_obligation_count!==result.delivery_ids.length||!result.events[0]||typeof result.events[0]!=='object'||typeof result.events[0].event_id!=='string'||result.events[0].event_id===''||result.events[0].delivery_obligation_count!==result.delivery_obligation_count||(result.acceptance_mode!=='DELIVERY'&&result.acceptance_mode!=='RECORD_ONLY')) { throw 'NotifyGateway HTTP 202 回执结构与当前合同不一致；请检查网关版本'; }
if (result.acceptance_mode==='RECORD_ONLY') { throw 'NotifyGateway 已接收事件但未生成投递任务：NO_ROUTE/RECORD_ONLY；请检查 zabbix-infra 路由'; }
if (result.delivery_obligation_count===0||result.events[0].route_status!=='ROUTED') { throw 'NotifyGateway DELIVERY 回执没有有效投递任务；请检查路由和 Channel'; }
return JSON.stringify({accepted:true,request_id:result.request_id,event_id:result.events[0].event_id,acceptance_mode:result.acceptance_mode,delivery_obligation_count:result.delivery_obligation_count,delivery_ids:result.delivery_ids,event_type:payload.event_type,test_mode:mode});

